#!/usr/bin/env python3
"""CSV Insights: small, dependency-free CSV filtering and aggregation CLI."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import OrderedDict
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Sequence


class InputError(Exception):
    """An error in the command arguments or source CSV."""


def parse_filter(value: str) -> tuple[str, str]:
    if "=" not in value:
        raise argparse.ArgumentTypeError(
            f"malformed filter {value!r}; expected COLUMN=VALUE"
        )
    column, expected = value.split("=", 1)
    if not column:
        raise argparse.ArgumentTypeError(
            f"malformed filter {value!r}; column name cannot be empty"
        )
    return column, expected


def parse_arguments(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Filter and aggregate RFC-4180 CSV data.")
    parser.add_argument("input", help="input CSV file")
    parser.add_argument("--where", action="append", type=parse_filter, default=[],
                        metavar="COLUMN=VALUE", help="exact-match filter (repeatable)")
    parser.add_argument("--group-by", metavar="COLUMN", help="column to group aggregates by")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN", help="numeric column to sum")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN", help="numeric column to average")
    parser.add_argument("--output", choices=("json", "csv"), default="json",
                        help="output format (default: json)")
    args = parser.parse_args(argv)
    if (args.sum_column or args.avg_column) and not args.group_by:
        parser.error("--sum and --avg require --group-by")
    if args.group_by and not (args.sum_column or args.avg_column):
        parser.error("--group-by requires --sum and/or --avg")
    return args


def read_csv(path: str) -> tuple[list[str], list[tuple[int, dict[str, str]]]]:
    try:
        with Path(path).open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.reader(source, strict=True)
            try:
                headers = next(reader)
            except StopIteration:
                raise InputError("input CSV is empty")
            if not headers or any(not header for header in headers):
                raise InputError("CSV headers must be non-empty")
            duplicates = sorted({header for header in headers if headers.count(header) > 1})
            if duplicates:
                raise InputError("CSV headers must be unique: " + ", ".join(duplicates))

            rows: list[tuple[int, dict[str, str]]] = []
            for row_number, fields in enumerate(reader, start=2):
                if len(fields) != len(headers):
                    raise InputError(
                        f"row {row_number} has {len(fields)} fields; expected {len(headers)}"
                    )
                rows.append((row_number, dict(zip(headers, fields))))
            return headers, rows
    except FileNotFoundError:
        raise InputError(f"input file not found: {path}")
    except PermissionError:
        raise InputError(f"cannot read input file: {path}")
    except UnicodeDecodeError as error:
        raise InputError(f"input is not valid UTF-8: {error}")
    except csv.Error as error:
        raise InputError(f"malformed CSV: {error}")


def require_columns(headers: list[str], columns: Sequence[str]) -> None:
    for column in columns:
        if column not in headers:
            raise InputError(f"unknown column: {column}")


def decimal_cell(value: str, row_number: int, column: str) -> Decimal:
    if not value:
        raise InputError(f"blank numeric value at row {row_number}, column {column}")
    try:
        number = Decimal(value)
    except InvalidOperation:
        raise InputError(f"invalid numeric value at row {row_number}, column {column}: {value!r}")
    if not number.is_finite():
        raise InputError(f"invalid numeric value at row {row_number}, column {column}: {value!r}")
    return number


def format_decimal(value: Decimal) -> str:
    if value == 0:
        return "0"
    text = format(value.normalize(), "f")
    return text.rstrip("0").rstrip(".") if "." in text else text


def aggregate(rows: list[tuple[int, dict[str, str]]], group_by: str, sum_column: str | None,
              avg_column: str | None) -> tuple[list[str], list[dict[str, str]]]:
    # Values retain their source-row positions so numeric errors name CSV rows.
    groups: OrderedDict[str, dict[str, Decimal | int]] = OrderedDict()
    for row_number, row in rows:
        key = row[group_by]
        state = groups.setdefault(key, {"count": 0})
        state["count"] = int(state["count"]) + 1
        if sum_column:
            state["sum"] = state.get("sum", Decimal(0)) + decimal_cell(row[sum_column], row_number, sum_column)  # type: ignore[operator]
        if avg_column:
            state["avg_total"] = state.get("avg_total", Decimal(0)) + decimal_cell(row[avg_column], row_number, avg_column)  # type: ignore[operator]

    output_headers = [group_by]
    if sum_column:
        output_headers.append(f"sum_{sum_column}")
    if avg_column:
        output_headers.append(f"avg_{avg_column}")
    output: list[dict[str, str]] = []
    for key in sorted(groups):
        state = groups[key]
        result = {group_by: key}
        if sum_column:
            result[f"sum_{sum_column}"] = format_decimal(state["sum"])  # type: ignore[arg-type]
        if avg_column:
            result[f"avg_{avg_column}"] = format_decimal(state["avg_total"] / int(state["count"]))  # type: ignore[operator,arg-type]
        output.append(result)
    return output_headers, output


def emit(headers: list[str], rows: list[dict[str, str]], output_format: str) -> None:
    if output_format == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False, separators=(",", ":"))
        sys.stdout.write("\n")
    else:
        writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def run(argv: Sequence[str] | None = None) -> int:
    args = parse_arguments(argv)
    headers, rows = read_csv(args.input)
    requested = [column for column, _ in args.where]
    requested += [column for column in (args.group_by, args.sum_column, args.avg_column) if column]
    require_columns(headers, requested)
    rows = [(row_number, row) for row_number, row in rows
            if all(row[column] == value for column, value in args.where)]
    if args.group_by:
        output_headers, output_rows = aggregate(rows, args.group_by, args.sum_column, args.avg_column)
    else:
        output_headers, output_rows = headers, [row for _, row in rows]
    emit(output_headers, output_rows, args.output)
    return 0


def main() -> None:
    try:
        raise SystemExit(run())
    except (InputError, OSError) as error:
        print(f"error: {error}", file=sys.stderr)
        raise SystemExit(1)


if __name__ == "__main__":
    main()
